using UnityEngine;
public sealed class GameManager:MonoBehaviour{public static GameManager Instance{get;private set;} [SerializeField]float startSpeed=8f,maxSpeed=22f,acceleration=.35f; public float RunSpeed{get;private set;} public float Distance{get;private set;} public int Coins{get;private set;} public int Score=>Mathf.FloorToInt(Distance*2f)+Coins*10; void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);RunSpeed=startSpeed;} void Update(){if(Time.timeScale==0)return;RunSpeed=Mathf.Min(maxSpeed,RunSpeed+acceleration*Time.deltaTime);Distance+=RunSpeed*Time.deltaTime;} public void AddCoin(int amount=1)=>Coins+=amount;}